const CACHE="nl-trails-v37",RUNTIME="nl-trails-runtime-v1";
const APP=["./","./index.html","./styles.css","./app.js","./manifest.webmanifest","./icon.svg","./trailway-data.js","./trails-data.js","./gnta-data.js","./north-data.js","./northern-peninsula-data.js","./northern-resource-roads.js","./mapped-data.js","./community-atv-data.js","./osm-poi-data.js","./flowers-cove-data.js","./expanded-walking-data.js","./provincial-parks-data.js","./driving-data.js","./activity-data.js","./enriched-data.js"];
self.addEventListener("install",event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(APP)).then(()=>self.skipWaiting())));
self.addEventListener("activate",event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith("nl-trails-v")&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener("fetch",event=>{if(event.request.method!=="GET")return;const url=new URL(event.request.url);if(url.origin===location.origin&&url.pathname.startsWith("/api/")){event.respondWith(fetch(event.request).catch(()=>new Response(JSON.stringify({offline:true,error:"Shared reports are unavailable offline"}),{status:503,headers:{"content-type":"application/json"}})));return}event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request).then(response=>{if(response.ok||response.type==="opaque"){const copy=response.clone();caches.open(url.origin===location.origin?CACHE:RUNTIME).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>url.origin===location.origin?caches.match("./index.html"):new Response("",{status:504}))))});
